import brainmass, brainstate, braintools, brainunit as u
import jax, jax.numpy as jnp
import numpy as np
brainstate.random.seed(0)
dt=.1*u.ms; conn=jnp.array([[0.,0.,0.],[1.,0.,0.],[0.,1.,0.]])
class Chain(brainstate.nn.Module):
 def __init__(self):
  super().__init__(); self.node=brainmass.EpileptorStep(3,x0=jnp.full(3,-2.4),Kvf=1.,Ks=.2); self.history=brainstate.nn.Delay(jnp.zeros(3),time=12*u.ms,init=braintools.init.Constant(0.))
 def update(self,stim,k,delay):
  self.history.update(self.node.x1.value); d=jnp.rint(delay/dt).astype(jnp.int32); delayed=self.history.retrieve_at_step(d); src=jnp.broadcast_to(delayed,conn.shape); c=brainmass.diffusive_coupling(src,self.node.x1.value,conn,k); self.node.update(c+stim); return self.node.x1.value

def run(k,delay,amp):
 with brainstate.environ.context(dt=dt):
  m=Chain(); brainstate.nn.init_all_states(m); ii=jnp.arange(15000)
  def step(i):
   on=(i>=1000)&(i<3000); s=jnp.array([jnp.where(on,amp,0.),0.,0.]);
