  return brainstate.transform.for_loop(step,ii)
ks=jnp.array([0.,.1,.2,.3,.4,.5,.7,1.]); ds=jnp.full(ks.shape,4.)*u.ms; amps=jnp.full(ks.shape,2.)
x=brainstate.transform.vmap(run)(ks,ds,amps); x=np.asarray(jax.device_get(x))
for ci,k in enumerate(np.asarray(ks)):
 print('k',k)
